def priority(task, state, k=1.0, m=2.0, c=1.0, c2=2.0, boost=1e6, boost2=1e5):
    slack = max(0.0, task.due - task.estimated_runtime - state.now)
    urgency = task.weight / max(task.estimated_runtime, 1e-6) * math.exp(-slack / (k * max(state.mean_est, 1e-6)))
    tier = m if task.tenant == 'premium' else 1.0
    wait = state.now - task.release
    ratio = wait / max(task.estimated_runtime, 1e-6)
    b = 1.0
    if ratio >= c2:
        b = boost
    elif ratio >= c:
        b = boost2
    return b * tier * urgency  # tuned (k=0.9,m=0.646,c=0.978,c2=0.943,boost=3.24e+05,boost2=3.22e+04)

def priority(task, state, k=0.5, m=2.0, q_hi=0.7):
    slack = max(0.0, task.due - task.estimated_runtime - state.now)
    tier = m if task.tenant == 'premium' else 1.0
    base = tier * task.weight / max(task.estimated_runtime, 1e-6) * math.exp(-slack / (k * max(state.mean_est, 1e-6)))
    load = state.queue_work / max(state.capacity, 1e-6)
    if load > q_hi:
        # under heavy load, emphasize tenant tier and weight more strongly
        return base * tier * task.weight
    return base  # tuned (k=0.792,m=0.889,q_hi=1.44)
